sed -i '/onResetFx = onResetFx/a \                    )\n                    if (track.instrumentType == InstrumentType.SAMPLE) {\n                        Spacer(modifier = Modifier.height(16.dp))\n                        var showRecorder by remember { mutableStateOf(false) }\n                        if (!showRecorder) {\n                            Button(\n                                onClick = { showRecorder = true },\n                                modifier = Modifier.fillMaxWidth(),\n                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFE040FB), contentColor = Color.Black)\n                            ) {\n                                Icon(Icons.Filled.Mic, contentDescription = null)\n                                Spacer(modifier = Modifier.width(8.dp))\n                                Text(if (track.customSamplePath != null) "NEUES SAMPLE AUFNEHMEN" else "SAMPLE AUFNEHMEN", fontWeight = FontWeight.Bold)\n                            }\n                            if (track.customSamplePath != null) {\n                                Text("Aktuelles Sample: ${track.customSamplePath.substringAfterLast(\\"/\\")}", color = Color.Gray, fontSize = 12.sp, modifier = Modifier.padding(top = 4.dp))\n                            }\n                        } else {\n                            AudioRecorderComponent(\n                                onRecordingFinished = { file ->\n                                    onSampleRecorded(file.absolutePath)\n                                    showRecorder = false\n                                },\n                                primaryColor = Color(0xFFE040FB)\n                            )\n                        }\n                    }' app/src/main/java/com/example/ui/screens/SequencerScreen.kt
